terraform {
  required_providers {
    proxmox = {
      source  = "bpg/proxmox"
      version = "~> 0.69"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.12"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

resource "proxmox_virtual_environment_container" "lxc" {
  node_name   = var.proxmox_node
  vm_id       = var.container_id
  description = var.description
  tags        = var.tags

  # Template
  operating_system {
    template_file_id = var.template
    type             = var.os_type
  }

  # Compute
  cpu {
    cores = var.cores
  }

  memory {
    dedicated = var.memory
    swap      = var.swap
  }

  # Root filesystem
  disk {
    datastore_id = var.rootfs_storage
    size         = var.rootfs_size
  }

  # Additional mount points
  dynamic "mount_point" {
    for_each = var.mount_points
    content {
      volume = mount_point.value.volume
      path   = mount_point.value.path
      backup = mount_point.value.backup
      quota  = mount_point.value.quota
    }
  }

  # Primary network - Container network (vmbr1, 10.100.x.x)
  network_interface {
    name   = "eth0"
    bridge = "vmbr1"
  }

  # Secondary network - LAN (vmbr0, 192.168.1.x) - only if lan_ip is set
  dynamic "network_interface" {
    for_each = var.lan_ip != "" ? [1] : []
    content {
      name   = "eth1"
      bridge = "vmbr0"
    }
  }

  initialization {
    hostname = var.name

    # eth0 - Container network (required)
    ip_config {
      ipv4 {
        address = var.container_ip
        gateway = var.container_gateway
      }
    }

    # eth1 - LAN network (optional)
    dynamic "ip_config" {
      for_each = var.lan_ip != "" ? [1] : []
      content {
        ipv4 {
          address = var.lan_ip
          gateway = null  # Don't set gateway on secondary interface
        }
      }
    }

    user_account {
      keys = [var.ssh_public_key]
    }
  }

  # GPU Device Passthrough and custom devices are configured via SSH
  # The API token doesn't have permission for device_passthrough (requires root@pam)
  # See null_resource.configure_gpu_passthrough below

  # Container features
  # Note: API tokens can only set features on unprivileged containers
  # For privileged containers, all features are configured via SSH in configure_container_features
  dynamic "features" {
    for_each = var.unprivileged ? [1] : []
    content {
      nesting = var.enable_nesting
    }
  }

  unprivileged = var.unprivileged

  # Lifecycle
  started       = var.start_on_create
  start_on_boot = var.start_on_boot

  # Lifecycle - ignore create-time-only attributes that would force replacement
  # These attributes cannot be changed on existing containers and must be ignored
  # for imported containers to work properly
  lifecycle {
    ignore_changes = [
      # These are create-time-only and would force replacement if changed
      operating_system,   # template_file_id
      initialization,     # user_account.keys, hostname
      unprivileged,       # cannot change privileged/unprivileged after creation
      disk,               # cannot change storage or reduce size after creation
      features,           # API token can't modify features on privileged containers (requires root@pam)
      tags,               # tags are additionally modified via cron jobs outside of Terraform
      device_passthrough, # GPU devices may be added manually via SSH (API token can't manage these)
      console,            # console settings may be modified outside of Terraform
      start_on_boot,      # may be set outside of Terraform
      mount_point,        # mount points configured outside Terraform (API token limitations)
      # Timeout values are not actual container properties, ignore them on imported resources
      timeout_clone,
      timeout_create,
      timeout_delete,
      timeout_start,
      timeout_update,
    ]
  }
}

# Configure container features via SSH to Proxmox host
# The API token cannot set keyctl or fuse - requires root@pam
# This configures:
#   - For privileged: lxc.apparmor.profile: unconfined (required for Docker)
#   - For all containers: features: nesting, keyctl, fuse (if enabled via variables)
resource "null_resource" "configure_container_features" {
  count = (var.enable_keyctl || var.enable_fuse || !var.unprivileged) && var.proxmox_ssh_host != "" ? 1 : 0

  depends_on = [proxmox_virtual_environment_container.lxc]

  triggers = {
    container_id   = var.container_id
    unprivileged   = var.unprivileged
    enable_nesting = var.enable_nesting
    enable_keyctl  = var.enable_keyctl
    enable_fuse    = var.enable_fuse
  }

  provisioner "remote-exec" {
    connection {
      type        = "ssh"
      host        = var.proxmox_ssh_host
      user        = "root"
      private_key = file(var.proxmox_ssh_private_key_path)
    }

    inline = [
      # Configure AppArmor profile for Docker support (only for privileged containers)
      var.unprivileged ? "echo 'Unprivileged container - skipping apparmor config'" : "grep -q 'lxc.apparmor.profile' /etc/pve/lxc/${var.container_id}.conf || echo 'lxc.apparmor.profile: unconfined' >> /etc/pve/lxc/${var.container_id}.conf",

      # Configure features via pct set (more reliable than direct conf editing)
      "pct set ${var.container_id} --features nesting=${var.enable_nesting ? 1 : 0},keyctl=${var.enable_keyctl ? 1 : 0},fuse=${var.enable_fuse ? 1 : 0}",

      # Restart container to apply changes and wait for it to come back up
      # The container must be rebooted for feature changes to take effect
      "if pct status ${var.container_id} | grep -q running; then pct stop ${var.container_id} && sleep 2 && pct start ${var.container_id} && echo 'Container restarted'; fi",

      # Wait for container to get an IP address after restart (up to 30 seconds)
      "echo 'Waiting for container to get IP...'",
      "for i in $(seq 1 15); do IP=$(pct exec ${var.container_id} -- ip -4 addr show eth0 2>/dev/null | grep inet | awk '{print $2}' | cut -d/ -f1); if [ -n \"$IP\" ] && [ \"$IP\" != \"pending\" ]; then echo \"Got IP: $IP\"; break; fi; sleep 2; done",

      "echo 'Container ${var.container_id} configured: nesting=${var.enable_nesting}, keyctl=${var.enable_keyctl}, fuse=${var.enable_fuse}'"
    ]
  }
}

# Configure GPU passthrough via SSH to Proxmox host
# The API token cannot set device_passthrough - requires root@pam
# This adds /dev/dri/card0, /dev/dri/renderD128, and /dev/kfd for AMD GPU
resource "null_resource" "configure_gpu_passthrough" {
  count = var.enable_gpu && var.proxmox_ssh_host != "" ? 1 : 0

  depends_on = [
    proxmox_virtual_environment_container.lxc,
    null_resource.configure_container_features
  ]

  triggers = {
    container_id = var.container_id
    enable_gpu   = var.enable_gpu
  }

  provisioner "remote-exec" {
    connection {
      type        = "ssh"
      host        = var.proxmox_ssh_host
      user        = "root"
      private_key = file(var.proxmox_ssh_private_key_path)
    }

    inline = [
      # Stop container before adding devices
      "if pct status ${var.container_id} | grep -q running; then pct stop ${var.container_id}; sleep 2; fi",

      # Add GPU devices via direct config modification
      # Using pct set --dev0/1/2 doesn't work for /dev/dri, so we modify conf directly
      "grep -q 'dev0:' /etc/pve/lxc/${var.container_id}.conf || echo 'dev0: /dev/dri/card0,gid=44' >> /etc/pve/lxc/${var.container_id}.conf",
      "grep -q 'dev1:' /etc/pve/lxc/${var.container_id}.conf || echo 'dev1: /dev/dri/renderD128,gid=104' >> /etc/pve/lxc/${var.container_id}.conf",
      "grep -q 'dev2:' /etc/pve/lxc/${var.container_id}.conf || echo 'dev2: /dev/kfd' >> /etc/pve/lxc/${var.container_id}.conf",

      # Add cgroup permissions for GPU (required for unprivileged containers)
      "grep -q 'lxc.cgroup2.devices.allow: c 226:' /etc/pve/lxc/${var.container_id}.conf || echo 'lxc.cgroup2.devices.allow: c 226:* rwm' >> /etc/pve/lxc/${var.container_id}.conf",
      "grep -q 'lxc.cgroup2.devices.allow: c 234:' /etc/pve/lxc/${var.container_id}.conf || echo 'lxc.cgroup2.devices.allow: c 234:* rwm' >> /etc/pve/lxc/${var.container_id}.conf",

      # Start container
      "pct start ${var.container_id}",

      # Wait for container to get IP
      "echo 'Waiting for container to get IP...'",
      "for i in $(seq 1 15); do IP=$(pct exec ${var.container_id} -- ip -4 addr show eth0 2>/dev/null | grep inet | awk '{print $2}' | cut -d/ -f1); if [ -n \"$IP\" ] && [ \"$IP\" != \"pending\" ]; then echo \"Got IP: $IP\"; break; fi; sleep 2; done",

      "echo 'GPU passthrough configured for container ${var.container_id}'"
    ]
  }
}

# Configure bind mount points via SSH to Proxmox host
# The API token cannot set bind mounts - requires root@pam
# This uses pct set to add mount points after container creation
resource "null_resource" "configure_mount_points" {
  count = length(var.mount_points) > 0 && var.proxmox_ssh_host != "" ? 1 : 0

  depends_on = [
    proxmox_virtual_environment_container.lxc,
    null_resource.configure_container_features,
    null_resource.configure_gpu_passthrough
  ]

  triggers = {
    container_id = var.container_id
    mount_points = jsonencode(var.mount_points)
  }

  provisioner "remote-exec" {
    connection {
      type        = "ssh"
      host        = var.proxmox_ssh_host
      user        = "root"
      private_key = file(var.proxmox_ssh_private_key_path)
    }

    inline = concat(
      # Stop container before adding mount points
      ["if pct status ${var.container_id} | grep -q running; then pct stop ${var.container_id}; sleep 2; fi"],

      # Add each mount point via pct set
      [for mp in var.mount_points : "pct set ${var.container_id} -mp${mp.slot} ${mp.volume},mp=${mp.path}"],

      # Start container
      ["pct start ${var.container_id}"],

      # Wait for container to get IP
      ["echo 'Waiting for container to get IP...'"],
      ["for i in $(seq 1 15); do IP=$(pct exec ${var.container_id} -- ip -4 addr show eth0 2>/dev/null | grep inet | awk '{print $2}' | cut -d/ -f1); if [ -n \"$IP\" ] && [ \"$IP\" != \"pending\" ]; then echo \"Got IP: $IP\"; break; fi; sleep 2; done"],

      ["echo 'Mount points configured for container ${var.container_id}: ${join(", ", [for mp in var.mount_points : mp.path])}'"]
    )
  }
}

# Wait for container to get DHCP IP
resource "time_sleep" "wait_for_ip" {
  depends_on = [
    proxmox_virtual_environment_container.lxc,
    null_resource.configure_container_features,
    null_resource.configure_gpu_passthrough,
    null_resource.configure_mount_points
  ]
  create_duration = "15s"
}

# =============================================================================
# Required Variables
# =============================================================================

variable "name" {
  description = "Name/hostname of the LXC container"
  type        = string
}

variable "container_id" {
  description = "Proxmox container ID (VMID)"
  type        = number
}

# =============================================================================
# Proxmox Connection
# =============================================================================

variable "proxmox_node" {
  description = "Proxmox node to create the container on"
  type        = string
}

variable "ssh_public_key" {
  description = "SSH public key content for root access"
  type        = string
}

# =============================================================================
# Compute Resources
# =============================================================================

variable "cores" {
  description = "Number of CPU cores"
  type        = number
  default     = 1
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 512
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 512
}

# =============================================================================
# Storage Configuration
# =============================================================================

variable "rootfs_storage" {
  description = "Storage pool for root filesystem"
  type        = string
  default     = "local-lvm"
}

variable "rootfs_size" {
  description = "Root filesystem size in GB"
  type        = number
  default     = 8
}

variable "mount_points" {
  description = "Additional mount points (bind mounts from host)"
  type = list(object({
    slot    = number                 # Mount point slot (0-255)
    path    = string                 # Path inside container (e.g., /tank/media)
    volume  = string                 # Host path or volume (e.g., /tank/media)
    size    = optional(string, null) # Size if creating new volume
    storage = optional(string, null) # Storage pool if creating new volume
    backup  = optional(bool, false)
    quota   = optional(bool, false)
  }))
  default = []
}

# =============================================================================
# Network Configuration
# =============================================================================
# Dual-network architecture:
#   - eth0 (vmbr1): Container network (10.100.x.x) - primary for all containers
#   - eth1 (vmbr0): LAN network (192.168.1.x) - optional, for services needing LAN access
#
# The container_ip is required and goes on eth0 (vmbr1).
# The lan_ip is optional and adds eth1 (vmbr0) for LAN-facing services.

variable "container_ip" {
  description = "Container network IP in CIDR notation (e.g., 10.100.1.100/16). Required."
  type        = string
}

variable "container_gateway" {
  description = "Container network gateway (Proxmox vmbr1 IP)"
  type        = string
  default     = "10.100.0.1"
}

variable "lan_ip" {
  description = "Optional LAN IP in CIDR notation (e.g., 192.168.1.100/24). Adds eth1 on vmbr0."
  type        = string
  default     = ""
}

variable "lan_gateway" {
  description = "LAN gateway IP (usually router)"
  type        = string
  default     = "192.168.1.1"
}

# =============================================================================
# Device Passthrough
# =============================================================================

variable "enable_gpu" {
  description = "Enable AMD GPU passthrough (/dev/dri/card0, /dev/dri/renderD128, /dev/kfd)"
  type        = bool
  default     = false
}

variable "devices" {
  description = "Additional devices to pass through to the container"
  type = list(object({
    path = string
    gid  = optional(number, null)
  }))
  default = []
}

# =============================================================================
# Template Configuration
# =============================================================================

variable "template" {
  description = "LXC template to use (e.g., local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "os_type" {
  description = "OS type (debian, ubuntu, alpine, etc.)"
  type        = string
  default     = "debian"
}

# =============================================================================
# Container Features
# =============================================================================

variable "unprivileged" {
  description = "Run as unprivileged container"
  type        = bool
  default     = true
}

variable "enable_nesting" {
  description = "Enable nesting (required for Docker/Podman)"
  type        = bool
  default     = false
}

variable "enable_fuse" {
  description = "Enable FUSE support"
  type        = bool
  default     = false
}

variable "enable_keyctl" {
  description = "Enable keyctl (required for some containers)"
  type        = bool
  default     = false
}

variable "start_on_boot" {
  description = "Start container on host boot"
  type        = bool
  default     = true
}

variable "start_on_create" {
  description = "Start container after creation"
  type        = bool
  default     = true
}

# =============================================================================
# Metadata
# =============================================================================

variable "description" {
  description = "Container description (supports markdown)"
  type        = string
  default     = ""
}

variable "tags" {
  description = "Tags for the container"
  type        = list(string)
  default     = []
}

# =============================================================================
# Import Configuration
# =============================================================================

variable "imported" {
  description = "Set to true for imported containers to ignore create-time-only attributes that would force replacement"
  type        = bool
  default     = false
}

# =============================================================================
# Proxmox Host SSH (for privileged container configuration)
# =============================================================================

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers with apparmor)"
  type        = string
  default     = ""
}

variable "proxmox_ssh_private_key_path" {
  description = "Path to SSH private key for Proxmox host"
  type        = string
  default     = ""
}

