# =============================================================================
# Required Variables
# =============================================================================

variable "name" {
  description = "Name of the LXC container"
  type        = string

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]*$", var.name))
    error_message = "Container name must start with a letter and contain only lowercase letters, numbers, and hyphens."
  }
}

variable "container_id" {
  description = "Proxmox container ID"
  type        = number

  validation {
    condition     = var.container_id >= 100 && var.container_id <= 999
    error_message = "Container ID must be between 100 and 999."
  }
}

variable "container_ip" {
  description = "Container network IP in CIDR notation (e.g., 10.100.1.100/16). Required."
  type        = string

  validation {
    condition     = can(regex("^10\\.100\\.[0-9]+\\.[0-9]+/[0-9]+$", var.container_ip))
    error_message = "Container IP must be in the 10.100.x.x/x CIDR format (e.g., 10.100.1.100/16)."
  }
}

variable "lan_ip" {
  description = "Optional LAN IP in CIDR notation (e.g., 192.168.1.100/24). For LAN-facing services."
  type        = string
  default     = ""

  validation {
    condition     = var.lan_ip == "" || can(regex("^192\\.168\\.1\\.[0-9]+/[0-9]+$", var.lan_ip))
    error_message = "LAN IP must be empty or in the 192.168.1.x/x CIDR format (e.g., 192.168.1.100/24)."
  }
}

variable "deploy_dir" {
  description = "Local directory containing deployment files (must include docker-compose.yml)"
  type        = string
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for container access"
  type        = string
}

# =============================================================================
# Container Configuration
# =============================================================================

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "cores" {
  description = "CPU cores"
  type        = number
  default     = 2

  validation {
    condition     = var.cores >= 1 && var.cores <= 16
    error_message = "CPU cores must be between 1 and 16."
  }
}

variable "memory" {
  description = "Memory in MB"
  type        = number
  default     = 2048

  validation {
    condition     = var.memory >= 256 && var.memory <= 65536
    error_message = "Memory must be between 256 MB and 65536 MB (64 GB)."
  }
}

variable "swap" {
  description = "Swap in MB"
  type        = number
  default     = 1024
}

variable "rootfs_size" {
  description = "Root filesystem size in GB"
  type        = number
  default     = 8

  validation {
    condition     = var.rootfs_size >= 4 && var.rootfs_size <= 500
    error_message = "Root filesystem size must be between 4 GB and 500 GB."
  }
}

variable "rootfs_storage" {
  description = "Storage pool for root filesystem"
  type        = string
  default     = "nvme-containers"
}

variable "unprivileged" {
  description = "Run as unprivileged container (true = more secure, false = privileged)"
  type        = bool
  default     = false
}

variable "enable_gpu" {
  description = "Enable AMD GPU passthrough (/dev/kfd, /dev/dri) for the container"
  type        = bool
  default     = false
}

variable "template" {
  description = "LXC template to use (should be Docker-ready)"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# =============================================================================
# Network Configuration
# =============================================================================

variable "container_gateway" {
  description = "Container network gateway (Proxmox vmbr1 IP)"
  type        = string
  default     = "10.100.0.1"
}

variable "lan_gateway" {
  description = "LAN gateway (router IP)"
  type        = string
  default     = "192.168.1.1"
}

# =============================================================================
# SSH Configuration
# =============================================================================

variable "ssh_public_key" {
  description = "SSH public key for root user"
  type        = string
  default     = ""
}

variable "proxmox_ssh_host" {
  description = "Proxmox host for SSH (for privileged container feature config)"
  type        = string
  default     = "homelab"
}

# =============================================================================
# File Sync Configuration
# =============================================================================

variable "target_path" {
  description = "Target path on container for config files"
  type        = string
  default     = "/config"
}

variable "config_owner" {
  description = "Owner for synced config files"
  type        = string
  default     = ""
}

variable "config_group" {
  description = "Group for synced config files"
  type        = string
  default     = ""
}

variable "file_permissions" {
  description = "Map of file paths to chmod permissions"
  type        = map(string)
  default     = {}
}

variable "delete_extra_files" {
  description = "Delete files on target that don't exist in source"
  type        = bool
  default     = true
}

variable "post_sync_commands" {
  description = "Additional commands to run after file sync"
  type        = list(string)
  default     = []
}

variable "exclude_patterns" {
  description = "List of glob patterns to exclude from file sync (e.g., ['migrated-dynamic/**'])"
  type        = list(string)
  default     = []
}

# =============================================================================
# Docker Compose Configuration
# =============================================================================

variable "docker_compose_up" {
  description = "Run docker compose up after deployment"
  type        = bool
  default     = true
}

variable "docker_compose_validate" {
  description = "Validate docker compose file"
  type        = bool
  default     = true
}

# =============================================================================
# Proxmox Notes Configuration
# =============================================================================

variable "enable_proxmox_notes" {
  description = "Enable automatic Proxmox notes generation"
  type        = bool
  default     = true
}

variable "service_name" {
  description = "Service name for Proxmox notes (defaults to container name)"
  type        = string
  default     = ""
}

variable "service_description" {
  description = "Service description for Proxmox notes"
  type        = string
  default     = ""
}

variable "service_urls" {
  description = "Service URLs for Proxmox notes"
  type        = map(string)
  default     = {}
}

variable "services" {
  description = "List of services running in the container"
  type = list(object({
    name = string
    port = number
    info = string
  }))
  default = []
}

variable "custom_notes" {
  description = "Custom notes to append to Proxmox notes"
  type        = string
  default     = ""
}

# =============================================================================
# Storage Configuration
# =============================================================================

variable "mount_points" {
  description = "List of mount points for the container"
  type = list(object({
    slot   = number
    path   = string
    volume = string
  }))
  default = []
}

# =============================================================================
# Portainer Edge Agent Configuration
# =============================================================================

variable "portainer_edge_id" {
  description = "Portainer Edge Agent ID (from 1Password or Portainer UI)"
  type        = string
  default     = ""
}

variable "portainer_edge_key" {
  description = "Portainer Edge Agent Key (base64-encoded, from 1Password or Portainer UI)"
  type        = string
  default     = ""
  sensitive   = true
}

# =============================================================================
# Miscellaneous
# =============================================================================

variable "tags" {
  description = "Additional tags for the container"
  type        = list(string)
  default     = []
}
